const handWritten = {
  type: 'section',
  props: {
    className: 'card',
    children: [
      { type: 'h1', props: { children: 'Hi' } },
      { type: 'p', props: { children: 'body' } },
    ],
  },
};

const fromHelper = createElement(
  'section',
  { className: 'card' },
  createElement('h1', null, 'Hi'),
  createElement('p', null, 'body')
);

assert.deepStrictEqual(handWritten, fromHelper);
console.log('desugar matches: true');

