function collectText(node) {
  if (typeof node === 'string') return node;
  if (node == null || typeof node !== 'object') return '';
  const children = node.props ? node.props.children : undefined;
  if (children === undefined) return '';
  const list = Array.isArray(children) ? children : [children];
  return list.map(collectText).join('');
}

const tree = {
  type: 'article', props: { children: [
    { type: 'h1', props: { children: 'Title' } },
    { type: 'div', props: { children: [
      { type: 'p', props: { children: 'Hello, ' } },
      { type: 'strong', props: { children: 'world' } },
    ] } },
    '!',
  ] },
};
console.log(JSON.stringify(collectText(tree)));

