exercises.prompt:
Because elements are plain data, you can transform a whole UI tree without rendering anything. Write `mapProps(element, fn)` that returns a NEW element tree where `fn` has been applied to every element's props object. Do not mutate the original tree.

Example — prefix every `className` with `"theme-dark "`:
```js
const tree = {
  type: 'div', props: { className: 'card', children: [
    { type: 'span', props: { className: 'title', children: 'Hi' } },
    { type: 'span', props: { children: 'no class' } },
  ] },
};
const themed = mapProps(tree, (props) =>
  props.className ? { ...props, className: 'theme-dark ' + props.className } : props
);
console.log('original untouched:', tree.props.children[0].props.className === 'title');
console.log('themed root:', themed.props.className);
console.log('themed child:', themed.props.children[0].props.className);
console.log('child without class kept:', themed.props.children[1].props.className === undefined);
console.log('new tree:', themed !== tree && themed.props.children[0] !== tree.props.children[0]);
```
Expected output:
```
original untouched: true
themed root: theme-dark card
themed child: theme-dark title
child without class kept: true
new tree: true
```

exercises.solution:
function mapProps(element, fn) {
  if (typeof element === 'string' || element == null) return element;
  const children = element.props ? element.props.children : undefined;
  const mappedChildren = Array.isArray(children)
    ? children.map((c) => mapProps(c, fn))
    : children !== undefined ? mapProps(children, fn) : undefined;
  const newProps = fn({ ...element.props, children: mappedChildren });
  return { ...element, props: newProps };
}

const tree = {
  type: 'div', props: { className: 'card', children: [
    { type: 'span', props: { className: 'title', children: 'Hi' } },
    { type: 'span', props: { children: 'no class' } },
  ] },
};
const themed = mapProps(tree, (props) =>
  props.className ? { ...props, className: 'theme-dark ' + props.className } : props
);
console.log('original untouched:', tree.props.children[0].props.className === 'title');
console.log('themed root:', themed.props.className);
console.log('themed child:', themed.props.children[0].props.className);
console.log('child without class kept:', themed.props.children[1].props.className === undefined);
console.log('new tree:', themed !== tree && themed.props.children[0] !== tree.props.children[0]);

